import z3

def solve_golfers(weeks, groups, group_size):
    num_golfers = groups * group_size

    # x[w][p] = group of golfer p in week w
    x = [[z3.Int(f"x_{w}_{p}") for p in range(num_golfers)] for w in range(weeks)]

    solver = z3.Solver()

    # Domain constraints
    for w in range(weeks):
        for p in range(num_golfers):
            solver.add(x[w][p] >= 0, x[w][p] < groups)

    # Group size constraints
    for w in range(weeks):
        for g in range(groups):
            solver.add(z3.Sum([z3.If(x[w][p] == g, 1, 0) for p in range(num_golfers)]) == group_size)

    # No pair in same group more than once
    for p1 in range(num_golfers):
        for p2 in range(p1 + 1, num_golfers):
            solver.add(z3.Sum([z3.If(x[w][p1] == x[w][p2], 1, 0) for w in range(weeks)]) <= 1)

    # Symmetry breaking
    # Week 0: golfer p is in group p // group_size
    for p in range(num_golfers):
        solver.add(x[0][p] == p // group_size)

    # Golfer 0 is always in group 0
    for w in range(weeks):
        solver.add(x[w][0] == 0)

    # Week 1: golfers 0, 4, 8, 12 are in group 0
    # Wait, golfer 0 is in group 0.
    # Let's just let Z3 solve it.

    solver.set("timeout", 50000)
    if solver.check() == z3.sat:
        m = solver.model()
        res = []
        for w in range(weeks):
            for p in range(num_golfers):
                res.append(m.evaluate(x[w][p]).as_long())
        print("SAT")
        print(res)
    else:
        print("UNSAT or TIMEOUT")

solve_golfers(5, 10, 4)

def verify(sol):
    weeks = 5
    groups = 10
    group_size = 4
    num_golfers = 40

    if len(sol) != 200:
        return False

    pairs = set()
    for w in range(weeks):
        week_groups = [[] for _ in range(groups)]
        for p in range(num_golfers):
            g = sol[w * num_golfers + p]
            week_groups[g].append(p)

        for g in range(groups):
            if len(week_groups[g]) != group_size:
                print(f"Week {w} group {g} has size {len(week_groups[g])}")
                return False
            for i in range(group_size):
                for j in range(i + 1, group_size):
                    p1 = week_groups[g][i]
                    p2 = week_groups[g][j]
                    if p1 > p2:
                        p1, p2 = p2, p1
                    if (p1, p2) in pairs:
                        print(f"Pair {p1}, {p2} repeated")
                        return False
                    pairs.add((p1, p2))
    return True

